SET timezone='UTC';SET test.clock='2026-09-14T08:30:00Z';
DELETE FROM unions;DELETE FROM union_clubs;DELETE FROM accounting_agreement_history;UPDATE clubs SET union_id=NULL;
UPDATE accounting_cash_rake_sources SET union_id=NULL,coordinator_union_id=NULL;
UPDATE accounting_rakeback_period_calculations SET coordinator_union_id=NULL;
SELECT assert_true(fn_process_weekly_accounting(NULL)->>'checked'='0' AND NOT EXISTS(SELECT 1 FROM union_accounting_runs),'standalone has no run or payment before Monday four Chicago time');
SET test.clock='2026-09-14T09:20:00Z';SET test.preparation_blocked='true';
CREATE TEMP TABLE failed_preparation AS SELECT fn_process_weekly_accounting(NULL)r;
SELECT assert_true((SELECT r->>'failed'='1' FROM failed_preparation) AND (SELECT status='failed' AND attempts=1 FROM union_accounting_runs),'standalone preparation refusal records one durable failed run');
SELECT assert_true((SELECT status='blocked' FROM accounting_period_recompute_requests) AND NOT EXISTS(SELECT 1 FROM accounting_routed_settlement_runs) AND (SELECT chip_treasury=200 FROM clubs),'failed preparation request survives without money or stage receipts');
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT attempts=2 FROM union_accounting_runs) AND (SELECT attempts=2 FROM accounting_period_recompute_requests) AND (SELECT count(*)=1 FROM financial_alerts),'unchanged standalone source failure is retryable without duplicate alerts');
SET test.preparation_blocked='false';SET test.forged_request='true';
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT status='failed' AND result->>'error'='weekly_accounting_calculation_incomplete' FROM union_accounting_runs),'an unconfirmed preparation-ready response cannot bypass durable request verification');
SET test.forged_request='false';SET test.weekly_failure='true';
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT result->>'error'='fixture weekly notification failure' FROM union_accounting_runs),'failure reaches the real weekly notification insertion');
SELECT assert_true((SELECT chip_treasury=200 FROM clubs) AND (SELECT sum(chip_balance)=0 FROM club_members) AND NOT EXISTS(SELECT 1 FROM accounting_routed_settlement_runs)
 AND NOT EXISTS(SELECT 1 FROM settlement_invoices) AND NOT EXISTS(SELECT 1 FROM settlement_periods),'weekly notification failure rolls real routed money, source receipts, all documents and periods back');
SELECT assert_true((SELECT status='complete' FROM accounting_period_recompute_requests),'completed preparation remains durable after downstream money rollback');
BEGIN;
SET LOCAL test.weekly_failure='false';
CREATE TEMP TABLE alert_baseline AS SELECT count(*)n FROM financial_alerts;
UPDATE accounting_cash_bank_receipts SET amount=19 WHERE rake_record_id=u(501);
SELECT fn_process_weekly_accounting(NULL);
SELECT fn_process_weekly_accounting(NULL);
SELECT count(*)-(SELECT n FROM alert_baseline) AS repeated_reconciliation_alerts FROM financial_alerts;
SELECT assert_true((SELECT count(*)-(SELECT n FROM alert_baseline)=1 FROM financial_alerts),'same reconciliation error does not alert twice because rollback regenerated its ledger UUIDs');
UPDATE clubs SET chip_treasury=1;
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT count(*)-(SELECT n FROM alert_baseline)=2 FROM financial_alerts),'a changed financial failure still produces a new alert');
ROLLBACK;
SET test.weekly_failure='false';
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT status='complete' AND result->>'accounting_version'='3' AND standalone_club_id=u(11) AND union_id IS NULL FROM union_accounting_runs),'standalone uses the existing durable run journal and complete witness');
SELECT assert_true((SELECT chip_treasury=153.40 FROM clubs) AND (SELECT sum(chip_balance)=46.60 FROM club_members) AND (SELECT count(*)=2 FROM accounting_routed_settlement_runs),'actual routed stages preserve exact standalone balances and two completion receipts');
SELECT assert_true((SELECT count(*)=1 FROM settlement_periods WHERE club_id=u(11) AND union_id IS NULL AND status='settled') AND (SELECT count(*)=1 FROM settlement_invoices WHERE invoice_type='club_weekly_accounting'),'standalone has one settled period and one real weekly statement');
SELECT assert_true((SELECT count(*)=11 FROM notifications) AND (SELECT count(*)=11 FROM social_messages),'all routed receipts and one weekly summary use real Messenger and notification delivery');
SELECT assert_true(fn_process_weekly_accounting(NULL)->>'checked'='0' AND (SELECT attempts=5 FROM union_accounting_runs),'complete standalone retry does not rerun money or increase attempts');
SELECT assert_true(NOT has_table_privilege('service_role','union_accounting_runs','INSERT') AND NOT has_table_privilege('service_role','union_accounting_runs','UPDATE'),'service-role defaults cannot mutate the durable run journal');
BEGIN;
UPDATE settlement_periods SET status='processing';
SELECT fn_process_weekly_accounting(NULL);
SELECT assert_true((SELECT status='settled' FROM settlement_periods),'complete-run fast path verifies period status and finishes its exact processing period');
ROLLBACK;
BEGIN;
UPDATE settlement_periods SET status='closed';
SELECT fn_mark_scope_accounting_settled('club',u(11),'2026-09-07 07:00Z','2026-09-14 07:00Z');
SELECT assert_true((SELECT status='closed' FROM settlement_periods),'already closed period is not downgraded');
ROLLBACK;
SET test.clock='2026-09-14T09:50:00Z';
SELECT assert_true(fn_process_weekly_accounting(NULL)->>'reason'='maintenance_window','coordinator respects maintenance time without changing completed runs');

SET test.clock='2026-09-14T09:20:00Z';
BEGIN;
ALTER TABLE accounting_routed_settlement_runs DISABLE TRIGGER USER;
DELETE FROM accounting_routed_settlement_runs WHERE round_no=2;
CREATE TEMP TABLE missing_route AS SELECT fn_process_weekly_accounting(NULL)r;
SELECT assert_true((SELECT r->>'checked'='1' AND r->>'failed'='1' FROM missing_route) AND (SELECT status='failed' FROM union_accounting_runs),'missing standalone routed receipt invalidates completion without replaying legacy paid entitlements');
SELECT assert_true((SELECT chip_treasury=153.40 FROM clubs) AND (SELECT count(*)=7 FROM settlement_invoices),'missing standalone stage evidence cannot pay or invoice again');
ROLLBACK;

BEGIN;
INSERT INTO clubs(id,chip_treasury,name,owner_id,is_union) VALUES(u(12),100,'Other Standalone',u(901),false);
INSERT INTO accounting_cash_rake_sources VALUES(u(404),u(504),u(301),u(12),NULL,NULL,'2026-09-10',0,jsonb_build_object('club_id',u(12),'tiers','[]'::jsonb));
CREATE TEMP TABLE exact_club_result AS SELECT fn_process_weekly_accounting_scope(NULL,u(11))r;
SELECT assert_true((SELECT r->>'checked'='0' AND r->>'success'='true' FROM exact_club_result) AND NOT EXISTS(SELECT 1 FROM union_accounting_runs WHERE standalone_club_id=u(12)),
 'exact-club coordinator call does not widen into another pending club');
ROLLBACK;
SELECT assert_true(refuses($$SELECT fn_process_weekly_accounting_scope(u(1),u(11))$$,'invalid_weekly_accounting_scope'),'coordinator refuses union and club IDs together');
